package com.ruoyi.framework.aspectj;

import com.ruoyi.common.core.domain.BaseEntity;
import com.ruoyi.common.core.domain.model.LoginUser;
import com.ruoyi.framework.security.context.SecurityContextUtils;
import org.aspectj.lang.JoinPoint;
import org.aspectj.lang.annotation.Aspect;
import org.aspectj.lang.annotation.Before;
import org.springframework.stereotype.Component;

@Aspect
@Component
public class DataScopeAspect {

    public static final String DATA_SCOPE = "dataScope";

    @Before("@annotation(controllerDataScope)")
    public void doBefore(JoinPoint point, com.ruoyi.common.annotation.DataScope controllerDataScope) {
        clearDataScope(point);
        LoginUser loginUser = SecurityContextUtils.getLoginUser();
        if (loginUser == null || loginUser.getUser().isAdmin()) {
            return;   // 管理员不围栏
        }
        StringBuilder sql = new StringBuilder();
        for (var role : loginUser.getUser().getRoles()) {
            switch (role.getDataScope()) {
                case "1" -> {
                    sql.setLength(0);
                    return;
                }
                case "2" -> sql.append(String.format(
                    " OR dept_id IN (SELECT dept_id FROM sys_role_dept WHERE role_id = %d)",
                    role.getRoleId()));
                case "3" -> sql.append(String.format(
                    " OR dept_id = %d", loginUser.getUser().getDeptId()));
                case "5" -> sql.append(String.format(
                    " OR user_id = %d", loginUser.getUser().getUserId()));
                default -> { }
            }
        }
        if (sql.length() > 0) {
            Object arg = point.getArgs()[0];
            if (arg instanceof BaseEntity entity) {
                entity.getParams().put(DATA_SCOPE, " AND (" + sql.substring(4) + ")");
            }
        }
    }

    /** 防残留：复用对象前先清掉上一次的过滤条件 */
    private void clearDataScope(JoinPoint joinPoint) {
        Object arg = joinPoint.getArgs()[0];
        if (arg instanceof BaseEntity entity) {
            entity.getParams().put(DATA_SCOPE, "");
        }
    }
}
